// TriggerAccountSync is the resolver for the triggerAccountSync field.
func (r *mutationResolver) TriggerAccountSync(ctx context.Context, accountID string) (*gqlModel.SyncRun, error) {
	userID, err := getUserIDFromContext(ctx)
	if err != nil {
		return nil, err
	}

	conn, err := r.SyncService.GetConnection(ctx, accountID)
	if err != nil {
		if r.UOW != nil && r.UOW.Account() != nil {
			acc, accErr := r.UOW.Account().GetByID(ctx, accountID)
			if accErr == nil && acc != nil && acc.UserID != userID {
				return nil, fmt.Errorf("unauthorized: account does not belong to current user")
			}
		}
	} else if conn.UserID != userID {
		return nil, fmt.Errorf("unauthorized: sync connection does not belong to current user")
	}

	run, err := r.SyncService.TriggerAccountSync(ctx, accountID)
	if err != nil {
		return nil, err
	}

	return mapSyncRunToGQL(run), nil
}

