// SyncCredentials is the resolver for the syncCredentials field.
func (r *queryResolver) SyncCredentials(ctx context.Context) ([]*gqlModel.SyncCredential, error) {
	userID, err := getUserIDFromContext(ctx)
	if err != nil {
		return nil, err
	}

	creds, err := r.SyncService.ListCredentials(ctx, userID)
	if err != nil {
		return nil, err
	}

	hasKraken := false
	res := make([]*gqlModel.SyncCredential, len(creds))
	for i, c := range creds {
		if strings.EqualFold(c.Provider, "KRAKEN") {
			hasKraken = true
		}
		res[i] = mapSyncCredentialToGQL(c)
	}

	// If Kraken is not configured in DB but present in ENV, append virtual credential
	if !hasKraken {
		if krakenKey := strings.TrimSpace(os.Getenv("KRAKEN_API_KEY")); krakenKey != "" {
			sourceEnv := "ENV"
			now := time.Now()
			res = append(res, &gqlModel.SyncCredential{
				ID:        "env-kraken",
				Provider:  "KRAKEN",
				Status:    "ACTIVE",
				Source:    &sourceEnv,
				CreatedAt: now,
				UpdatedAt: now,
			})
		}
	}

	return res, nil
}

func maskPhone(p string) string {
	if len(p) <= 6 {
		return "***"
	}
	return p[:3] + "..." + p[len(p)-3:]
}

